Plan: Read the item number from Calc!A10, search the three supplier sheets in order for a matching item, and write the corresponding supplier name into Calc!B7. If no supplier contains the item, leave B7 empty. Save the workbook with the computed value.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Calc"]
vws = vals["Calc"]

item = vws["A10"].value

def norm_key(x):
    if x is None:
        return None
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x).strip()

target = norm_key(item)

answer = None
if target is not None:
    for sheet_name in ("Supplier_1", "Supplier_2", "Supplier_3"):
        if sheet_name not in vals.sheetnames:
            continue
        s = vals[sheet_name]
        for row in s.iter_rows(min_row=2, max_col=2, values_only=True):
            if norm_key(row[0]) == target:
                answer = row[1]
                break
        if answer is not None:
            break

if isinstance(answer, str):
    answer = answer.strip()

ws["B7"] = answer

wb.save(OUT)

print("item:", item)
print("answer:", answer)
